const BIG = { mass: 40, seat: 1 };
const UNIT = 60;
const PIVOT = [0, 0, 44];
const BEAM = [400, 34, 6];

figure({
  title: "Seesaw",
  icon: "⚖️",
  level: "5-8",
  mode: "iso",
  question: "Why does distance matter as much as weight on a seesaw?",
  caption:
    "Each rider has a turning effect on the beam: their mass times their distance from the pivot. The beam balances when the two turning effects are equal, so half the mass needs twice the distance.",
  leavesOut: "The beam's own weight and friction at the pivot. Riders are treated as sitting at a single point.",
  try: "Balance the 40 kg rider with a 25 kg rider.",
  controls: [
    { id: "mass", label: "Mass of the right rider", min: 10, max: 60, step: 5, value: 20, unit: "kg" },
    { id: "seat", label: "Distance from the pivot", min: 0.4, max: 3, step: 0.1, value: 1, unit: "m" },
  ],
  size: [600, 300],
  camera: { azimuth: 80, elevation: 22 },

  model(s) {
    const left = BIG.mass * BIG.seat;
    const right = s.mass * s.seat;
    const net = right - left;
    return { left, right, net, tilt: Math.max(-11, Math.min(11, (-net / 40) * 11)), level: Math.abs(net) < 1.2 };
  },
  goal: (m, s) => m.level && Math.abs(s.mass - 25) < 0.5,
  readout: (m, s) => `Left: ${BIG.mass} kg × ${BIG.seat.toFixed(1)} m = ${m.left.toFixed(0)} · Right: ${s.mass.toFixed(0)} kg × ${s.seat.toFixed(1)} m = ${m.right.toFixed(0)} · ${m.level ? "Balanced" : m.net > 0 ? "Right side falls" : "Left side falls"}`,

  draw(m, s, kit) {
    const spin = { about: "y", deg: m.tilt, pivot: PIVOT };
    const top = PIVOT[2] + BEAM[2];
    const rider = (seat, mass, tint) => {
      const side = 10 + mass * 0.32;
      const head = kit.turn([seat * UNIT, 0, top + side], spin);
      const centre = kit.turn([seat * UNIT, 0, top + side / 2], spin);
      return [centre, [kit.tilted(centre, [side, side, side], { ...spin, pivot: centre, tint }), kit.label(head, `${mass.toFixed(0)} kg`, { dy: -8, size: 12, fill: "ink", weight: 600 })]];
    };
    const ticks = [];
    for (let step = -3; step <= 3; step++) {
      if (!step) continue;
      const a = kit.turn([step * UNIT, -BEAM[1] / 2, top], spin);
      const b = kit.turn([step * UNIT, -BEAM[1] / 2 + 9, top], spin);
      ticks.push(kit.line3(a, b, { tone: "mid" }));
    }
    return [
      kit.halo(-180, -34, 360, 68),
      kit.box(-200, -38, -8, 400, 76, 8, { tone: "mid", r: 6, bevel: 1 }),
      kit.box(-16, -24, 0, 32, 48, 30, { tone: "mid", r: 3 }),
      kit.post(0, 0, 9, 30, 11, { tone: "mid" }),
      kit.tilted([0, 0, PIVOT[2] + BEAM[2] / 2], BEAM, { ...spin, tint: "warm" }),
      ticks,
      kit.paint([rider(-BIG.seat, BIG.mass, "cool"), rider(s.seat, s.mass, "accent")]),
    ];
  },
});

parts.args:
{"source": "const LAT = 40, TILT = 23.4, PX = 50, GY = 340, X0 = 260, R = 260;
const RAD = Math.PI / 180;
const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const LONG = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const NOTE = { 3: " (spring starts)", 6: " (longest day)", 9: " (autumn starts)", 12: " (shortest day)" };

function decl(m, tilted) { return tilted ? TILT * Math.cos((2 * Math.PI * (m - 6)) / 12) : 0; }
function geo(alt) {
  const sa = Math.sin(alt * RAD), ca = Math.cos(alt * RAD);
  const L = PX / sa;
  const cx = X0 + L / 2;
  const u = [-ca, -sa];
  return { L, u, sun: [cx + u[0] * R, GY + u[1] * R] };
}
function seasonOf(mi) {
  if (mi === 12 || mi <= 2) return "winter";
  if (mi <= 5) return "spring";
  if (mi <= 8) return "summer";
  return "autumn";
}
function f_clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }

figure({
  title: "Sunlight and the seasons",
  icon: "☀️",
  level: "5-8",
  depth: "deep",
  mode: "flat",
  size: [840, 420],
  question: "Why is summer hotter than winter?",
  caption:
    "Earth's axis is tilted, so in summer your half leans toward the Sun. The Sun climbs higher and its light is concentrated: the same sunlight lands on less ground. Days are longer too. It isn't distance: Earth is closest to the Sun in early January.",
  leavesOut:
    "Air, clouds and oceans matter too, and the hottest weeks come about a month after the longest day because land and sea take time to warm up. The orbit is drawn squashed and not to scale; it is nearly a circle.",
  try: "Find the day when each square metre of ground gets the most sunlight.",
  controls: [
    {
      id: "month", label: "Date (the 21st of each month)", min: 1, max: 12, step: 1, value: 12,
      format: (v) => { const i = Math.round(v); return `21 ${LONG[i - 1]}${NOTE[i] || ""}`; },
    },
    { id: "tilt", label: "Earth's tilt (23°)", type: "toggle", value: true },
  ],
  tour: true,

  model(s) {
    const d = decl(s.month, s.tilt);
    const alt = 90 - LAT + d;
    const g = geo(alt);
    const patch = Math.round((g.L / PX) * 100) / 100;          // metres of ground, 2 dp
    const share = Math.round(100 / patch);                       // units per m², from the rounded patch
    const x = -Math.tan(LAT * RAD) * Math.tan(d * RAD);
    const hours = (2 * Math.acos(f_clamp(x, -1, 1)) / RAD) / 15;
    const mi = Math.round(s.month);
    return {
      d, alt, g, patch, share, hours, mi,
      altR: Math.round(alt), hoursR: Math.round(hours),
      season: seasonOf(mi),
      exact: 100 * Math.sin(alt * RAD),
    };
  },
  goal: (m, s) => s.tilt && m.mi === 6,
  readout: (m, s) => {
    const date = `21 ${LONG[m.mi - 1]}`;
    const sum = `100 units of sunlight ÷ ${m.patch.toFixed(2)} m² of ground = ${m.share} units on each m².`;
    if (!s.tilt) {
      return [
        `No tilt: the noon Sun is ${m.altR}° high every day of the year.`,
        sum,
        `Every day has ${m.hoursR} h of daylight. Nothing changes, so there are no seasons!`,
      ];
    }
    const kind = m.d > 12 ? `Strong, concentrated sunlight for ${m.hoursR} h a day` :
      m.d < -12 ? `Weak, spread-out sunlight for only ${m.hoursR} h a day` :
        `Medium sunlight for about ${m.hoursR} h a day`;
    return [
      `${date}: the noon Sun is ${m.altR}° above the horizon.`,
      sum,
      `${kind}: ${m.season}.`,
    ];
  },

  draw(m, s, f) {
    const out = [];
    // ---- scene: sky and ground
    out.push(f.rect(0, 0, 560, GY, { fill: "sky" }));
    out.push(f.rect(0, GY, 560, 420 - GY, { fill: "earth" }));
    out.push(f.text(16, 28, "Your town, 40° north, at noon", { anchor: "start", size: 15, fill: "mid" }));

    // sun path (all possible noon positions) and the real June / December marks
    const pts = [];
    for (let a = 24; a <= 76; a += 2) pts.push(geo(a).sun);
    out.push(f.poly(pts, { open: true, fill: "none", stroke: "lo", width: 2, dash: "4 6" }));
    const pJ = geo(90 - LAT + TILT).sun, pD = geo(90 - LAT - TILT).sun;
    out.push(f.circle(pJ[0], pJ[1], 5, { fill: "lo" }));
    out.push(f.text(pJ[0] - 34, pJ[1] + 5, "June 21", { anchor: "end", size: 14, fill: "mid" }));
    out.push(f.circle(pD[0], pD[1], 5, { fill: "lo" }));
    out.push(f.text(pD[0] - 6, pD[1] + 46, "Dec 21", { size: 14, fill: "mid" }));

    // the beam: same width every day
    const { L, u, sun } = m.g;
    const p1 = [X0, GY], p2 = [X0 + L, GY];
    const rays = [];
    for (let i = 0; i < 5; i++) {
      const fr = (i + 0.5) / 5;
      const gx = X0 + fr * L;
      const back = R - 70;
      rays.push(f.arrow(gx + u[0] * back, GY + u[1] * back, gx, GY - 2, { stroke: "warm", width: 2 }));
    }
    const k = 135;
    const a1 = [p1[0] + u[0] * k, p1[1] + u[1] * k];
    const t2 = k + L * Math.cos(m.alt * RAD);
    const a2 = [p2[0] + u[0] * t2, p2[1] + u[1] * t2];
    const nx = (a1[0] - a2[0]) / PX, ny = (a1[1] - a2[1]) / PX;  // unit, pointing out of the beam
    out.push(f.part("Sunbeam", [
      f.poly([p1, p2, [p2[0] + u[0] * R, p2[1] + u[1] * R], [p1[0] + u[0] * R, p1[1] + u[1] * R]], { fill: "warm-soft", opacity: 0.85 }),
      rays,
      f.line(a1[0], a1[1], a2[0], a2[1], { stroke: "ink", width: 2 }),
      f.text(a1[0] + nx * 24, a1[1] + ny * 24 + 5, "1 m", { size: 14, fill: "ink" }),
    ], "A beam of sunlight 1 m wide. It carries the same 100 units of sunlight every day; only its angle changes."));
    out.push(f.part("Noon Sun", f.circle(sun[0], sun[1], 24, { fill: "sun", glow: true }),
      "The Sun at midday. The dashed path shows every noon position through the year: high in June, low in December."));

    // the lit patch on the ground, brighter when concentrated
    const by = GY + 50;
    out.push(f.part("Lit ground", [
      f.rect(X0, GY - 3, L, 7, { fill: "warm", r: 3, opacity: f.map(m.share, 40, 100, 0.45, 1) }),
      f.line(X0, by, X0 + L, by, { stroke: "accent", width: 3 }),
      f.line(X0, by - 6, X0, by + 6, { stroke: "accent", width: 3 }),
      f.line(X0 + L, by - 6, X0 + L, by + 6, { stroke: "accent", width: 3 }),
      f.text(X0 + L + 10, by + 5, `${m.patch.toFixed(2)} m`, { anchor: "start", size: 15, fill: "accent", weight: 600 }),
      f.text(X0 - 10, by + 5, "lit ground", { anchor: "end", size: 14, fill: "accent" }),
    ], "Where the beam lands. A low Sun spreads the same sunlight over more ground, so each square metre warms less."));
    out.push(f.ruler(X0, X0 + 3 * PX, GY + 12, { count: 6, every: 2, label: (i) => `${i / 2} m` }));

    // a small house for scale and place
    const hx = 470;
    out.push(f.shadow(hx + 30, GY, 40));
    out.push(f.rect(hx, GY - 44, 60, 44, { fill: "paper", r: 3 }));
    out.push(f.poly([[hx - 6, GY - 42], [hx + 30, GY - 70], [hx + 66, GY - 42]], { fill: "hot", opacity: 0.8 }));
    out.push(f.rect(hx + 22, GY - 24, 14, 24, { fill: "mid", r: 2 }));
    out.push(f.rect(hx + 42, GY - 36, 12, 10, { fill: "cool-soft", r: 2 }));

    // ---- orbit inset
    const ox = 705, oy = 120, rx = 100, ry = 30;
    out.push(f.rect(585, 12, 245, 175, { fill: "soft", r: 12 }));
    out.push(f.text(ox, 33, "Earth's orbit (not to scale)", { size: 14, fill: "mid" }));
    out.push(f.ellipse(ox, oy, rx, ry, { fill: "none", stroke: "lo", width: 1.5, dash: "3 5" }));
    const th = (2 * Math.PI * (s.month - 6)) / 12;
    const ex = ox - rx * Math.cos(th), ey = oy + ry * Math.sin(th);
    const share = (((0.25 - (s.month - 6) / 12) % 1) + 1) % 1;
    const tiltDeg = s.tilt ? TILT : 0;
    const ax = Math.sin(tiltDeg * RAD) * 19, ay = Math.cos(tiltDeg * RAD) * 19;
    const earth = f.part("Tilted Earth", [
      f.phase(ex, ey, 11, share, { lit: "cool", dark: "#34405e" }),
      f.line(ex - ax, ey + ay, ex + ax, ey - ay, { stroke: "ink", width: 2 }),
      f.text(ex + ax * 1.2 + (s.tilt ? 6 : 10), ey - ay * 1.2 + 6, "N", { size: 13, fill: "ink" }),
    ], "Earth's axis always points the same way in space. In June the north half leans toward the Sun; in December it leans away.");
    const sunI = [f.circle(ox, oy, 15, { fill: "sun", glow: true }), f.text(ox, oy + 34, "Sun", { size: 13, fill: "mid" })];
    out.push(ey < oy ? [earth, sunI] : [sunI, earth]);
    let lean;
    if (!s.tilt) lean = "No tilt: neither half leans";
    else if (m.d > 12) lean = "North half leans toward the Sun";
    else if (m.d < -12) lean = "North half leans away from the Sun";
    else lean = "Neither half leans toward the Sun";
    out.push(f.text(ox, 177, lean, { size: 13, fill: "ink" }));

    // ---- plot: sunlight per m² through the year
    out.push(f.part("Year graph", f.plot(640, 232, 175, 120, {
      x: [1, 12], y: [0, 100],
      xTicks: 12, yTicks: 3,
      xTick: (v) => MONTHS[Math.round(v) - 1][0],
      yLabel: "Noon sunlight per m²",
      xLabel: "month (21st)",
      lines: [
        ...(s.tilt ? [] : [{ fn: (x) => 100 * Math.sin((90 - LAT + decl(x, true)) * RAD), stroke: "lo", dash: "4 4" }]),
        { fn: (x) => 100 * Math.sin((90 - LAT + decl(x, s.tilt)) * RAD), stroke: "warm" },
      ],
      marks: [{ x: s.month, y: m.exact, fill: "accent", drop: true }],
    }), "Units of sunlight landing on each square metre at noon, through the year. The dot is today's date."));
    return out;
  },
});
"}
